; legend.asm -- chapter 34: the keys as the BIOS types them
; generated by gen34.py
        INCLUDE "msx.inc"
        OUTPUT "legend.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
rows    EQU VARS                ; rows 0 to 5 of the matrix, this frame
before  EQU VARS + 8            ; and the last frame
cell    EQU VARS + 16           ; the place of the last key gone down
; The BIOS's interrupt reads the keyboard every third frame and puts the
; characters of the keys in its buffer. The program reads rows 0 to 5 from
; the ports every frame, keeps the place of the last key gone down, and
; prints each character the BIOS gives in that key's place.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $00          ; Graphic I
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $80          ; colours  $2000
        VDP_REG 4, $00          ; patterns $0000
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: the BIOS's set, from CGTABL
        ld hl, (CGTABL)
        ld e, 8
        call send
        VRAM_WRITE $0008        ; and the two boxes at 1 and 2
        ld hl, boxes
        ld bc, 16 << 8 | VDP_DATA
        otir
        VRAM_WRITE $2000        ; black ink on white paper
        ld a, $1F
        ld b, 32
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; the names
        ld hl, names
        ld e, 3
        call send
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, before           ; nothing held before the first frame
        ld b, 6
.none:  ld (hl), $FF
        inc hl
        djnz .none
        ld hl, $1800
        ld (cell), hl
        im 1                    ; the interrupt: the BIOS's routine at $0038
        VDP_REG 1, $E0          ; the display on, and the frame's signal
main:   ei
        halt                    ; the frame, and the BIOS's interrupt routine
        di
        ld hl, rows
        ld b, 6
        call scan
        call fresh
        call CHSNS              ; a character in the BIOS's buffer? (EI)
        jr z, main
        call CHGET              ; take it
got:    di
        ld c, a
        ld hl, (cell)
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        ld a, c
        out (VDP_DATA), a       ; the character, in the place of its key
        jr main

; fresh: a key of rows 0-5 that was up last frame and is down now: its place
; on the screen into cell; and this frame's rows into before. Uses A, B, C,
; D, E, HL
fresh:  ld hl, rows
        ld de, before
        ld c, 0                 ; the row
.row:   ld a, (de)              ; last frame's keys
        ld b, a
        ld a, (hl)              ; this frame's
        ld (de), a
        cpl
        and b                   ; 1: down now, up before
        call nz, place
        inc hl
        inc de
        inc c
        ld a, c
        cp 6
        jr nz, .row
        ret

; place: A = a key's bit (a 1), C = its row: the key's place on the screen
; into cell, $1800 + 32 x line + column. Keeps C, DE, HL
place:  push hl
        ld b, 19                ; bit 0's column; bit 7's is 5
.bit:   rrca
        jr c, .col
        dec b
        dec b
        jr .bit
.col:   ld a, c                 ; the line: 3 + 2 x row
        add a, a
        add a, 3
        ld h, 0
        ld l, a
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        ld a, b
        add a, l
        ld l, a
        ld a, h
        add a, $18
        ld h, a
        ld (cell), hl
        pop hl
        ret

; scan: B rows of the keyboard, from row 0, into the bytes from HL; a bit at 0
; is a key held down. Port C's top four bits drive the cassette motor and its
; output, the CAPS lamp and the click (chapter 3): they go back as they were.
; The interrupts must be off. Uses A, B, C, HL
scan:   in a, (PPI_C)           ; 12
        and $F0                 ;  8  the top four bits
        ld c, a                 ;  5  and row 0
.row:   ld a, c                 ;  5
        out (PPI_C), a          ; 12  the row
        in a, (PPI_B)           ; 12  its eight keys
        ld (hl), a              ;  8
        inc hl                  ;  7
        inc c                   ;  5  the next row
        djnz .row               ; 14 / 9
        ret                     ; 11

; at: the next characters go to row D, column E (chapter 30)
at:     ld a, d
        rrca
        rrca
        rrca
        ld c, a
        and $E0
        or e
        out (VDP_CTRL), a
        ld a, c
        and $03
        or $18 | $40
        out (VDP_CTRL), a
        ret

; cells: A as eight boxes from bit 7, a filled box for a 0 (a key held) and
; an empty one for a 1, from the address set. Uses A, B, L
cells:  ld l, a
        ld b, 8
.cell:  ld a, 2
        rlc l                   ; the next bit, into the carry
        jr nc, .put             ; 0: held
        ld a, 1
.put:   out (VDP_DATA), a
        djnz .cell
        ret

; hex: A as two hexadecimal digits, from the address set. Uses A, C
hex:    ld c, a
        rrca
        rrca
        rrca
        rrca
        call .digit
        ld a, c
.digit: and $0F
        add a, '0'
        cp '9' + 1
        jr c, .out
        add a, 'A' - '9' - 1
.out:   out (VDP_DATA), a
        ret

; send: E blocks of 256 bytes from HL to the VDP
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret
names:                          ; 24 rows of 32
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $72, $6F, $77, $20, $20, $37, $20, $36, $20, $35, $20, $34, $20, $33, $20, $32
